INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00017000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 17), 'unit17-lesson1', 'There is / There are (Present)', '''There is'' and ''there are'' are used to talk about the existence of things in the present. Use ''there is'' (or ''there''s'') with singular nouns and uncountable nouns. Use ''there are'' with plural nouns.', '{"details":[{"concept":"There is + singular noun","explanation":"Use ''there is'' when talking about one thing.","example":"There is a book on the desk.","burmese":"စာအုပ်တစ်အုပ် ပွင့်ပေါ်မှာ ရှိတယ်။"},{"concept":"There is + uncountable noun","explanation":"Use ''there is'' with uncountable nouns like milk, water, bread.","example":"There is some milk in the fridge.","burmese":"ရေခဲသတ္တုထဲမှာ နွားနို့ အနည်းငယ်ရှိတယ်။"},{"concept":"There are + plural noun","explanation":"Use ''there are'' when talking about more than one thing.","example":"There are books on the desk.","burmese":"စာအုပ်တွေ ပွင့်ပေါ်မှာ ရှိတယ်။"},{"concept":"Negative forms","explanation":"Use ''there isn''t'' with singular/uncountable nouns and ''there aren''t'' with plural nouns. Use ''there isn''t any'' or ''there aren''t any'' when indicating zero quantity.","example":"There isn''t a book on the desk. / There aren''t any people at the party.","burmese":"စာအုပ်တစ်အုပ် ပွင့်ပေါ်မှာ မရှိဘူး။ / ပါတီမှာ လူတွေ မရှိကြဘူး။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00017001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 17), 'unit17-lesson2', 'Questions with There is / There are', 'To form questions, put ''is'' or ''are'' before ''there''. Use ''Is there'' with singular nouns and ''Are there'' with plural nouns. To ask about quantities, use ''How many + plural noun + are there?''', '{"details":[{"concept":"Is there + singular noun?","explanation":"Ask about one thing with ''Is there''.","example":"Is there a dog in the supermarket?","burmese":"စူပါမားကက်ထဲမှာ ခွေးတစ်ကောင် ရှိလား။"},{"concept":"Are there + plural noun?","explanation":"Ask about many things with ''Are there''.","example":"Are there cats on the sofa?","burmese":"ဆိုဖာပေါ်မှာ ကြောင်တွေ ရှိလား။"},{"concept":"Are there any + noun?","explanation":"Use ''any'' in questions with plural or uncountable nouns.","example":"Are there any hamsters in Asia?","burmese":"အာရှတိုက်မှာ ဟမ်စတာ တွေ ရှိလား။"},{"concept":"How many + plural + are there?","explanation":"Ask about quantity with ''How many''.","example":"How many students are there in your class?","burmese":"မင်းတို့ အတန်းထဲမှာ ကျောင်းသား ဘယ်နှစ်ယောက် ရှိလဲ။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00017000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 17), 'unit17-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1701,"question":"There ________ a bird in the sky.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with singular nouns. ''A bird'' is singular. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ သုံးပါ။","points":1},{"id":1702,"question":"There ________ two birds in the sky.","options":["is","are","was"],"answer":"are","explanation":"''There are'' is used with plural nouns. ''Two birds'' is plural. ''There is'' is for singular nouns. ''There was'' is past tense. ''There are'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1703,"question":"There ________ many questions to answer.","options":["is","are","was"],"answer":"are","explanation":"''There are'' is used with plural nouns. ''Many questions'' is plural. ''There is'' is for singular nouns. ''There was'' is past tense. ''There are'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1704,"question":"There ________ any money in the bank.","options":["isn''t","aren''t","wasn''t"],"answer":"isn''t","explanation":"''There isn''t'' is used with uncountable nouns. ''Money'' is uncountable. ''There aren''t'' is for plural nouns. ''There wasn''t'' is past tense. ''There isn''t'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ သုံးပါ။","points":1},{"id":1705,"question":"There ________ sixteen candles on my birthday cake.","options":["is","are","isn''t"],"answer":"are","explanation":"''There are'' is used with plural nouns. ''Sixteen candles'' is plural. ''There is'' is for singular nouns. ''There isn''t'' is negative singular. ''There are'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1706,"question":"There ________ a broken pencil in the pencil sharpener.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with singular nouns. ''A broken pencil'' is singular. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ သုံးပါ။","points":1},{"id":1707,"question":"There ________ no place like home.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with singular nouns. ''No place'' is singular. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ သုံးပါ။","points":1},{"id":1708,"question":"________ there any dogs in the park?","options":["Are","Is","Were"],"answer":"Are","explanation":"''Are there'' is used with plural nouns. ''Dogs'' is plural. ''Is there'' is for singular nouns. ''Were there'' is past tense. ''Are there'' ကို အရာဝတ္ထု အများကြီးနဲ့ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1709,"question":"________ there any orange juice in the freezer?","options":["Is","Are","Were"],"answer":"Is","explanation":"''Is there'' is used with uncountable nouns. ''Orange juice'' is uncountable. ''Are there'' is for plural nouns. ''Were there'' is past tense. ''Is there'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1710,"question":"________ there any hamsters in Asia?","options":["Are","Is","Was"],"answer":"Are","explanation":"''Are there'' is used with plural nouns. ''Hamsters'' is plural. ''Is there'' is for singular nouns. ''Was there'' is past tense. ''Are there'' ကို အရာဝတ္ထု အများကြီးနဲ့ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1711,"question":"How many dogs ________ there in the park?","options":["are","is","were"],"answer":"are","explanation":"''How many'' is followed by a plural noun and ''are there''. ''Dogs'' is plural. ''Is'' is for singular nouns. ''Were'' is past tense. ''How many'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1712,"question":"How many Star Wars films ________ there?","options":["are","is","was"],"answer":"are","explanation":"''How many'' is followed by a plural noun and ''are there''. ''Films'' is plural. ''Is'' is for singular nouns. ''Was'' is past tense. ''How many'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1713,"question":"________ a security guard in the shop?","options":["Is there","Are there","Was there"],"answer":"Is there","explanation":"''Is there'' is used with singular nouns. ''A security guard'' is singular. ''Are there'' is for plural nouns. ''Was there'' is past tense. ''Is there'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1714,"question":"There ________ any people at the restaurant.","options":["aren''t","isn''t","weren''t"],"answer":"aren''t","explanation":"''There aren''t'' is used with plural nouns. ''People'' is plural. ''There isn''t'' is for singular/uncountable nouns. ''There weren''t'' is past tense. ''There aren''t'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1715,"question":"There ________ any water in the swimming pool.","options":["isn''t","aren''t","wasn''t"],"answer":"isn''t","explanation":"''There isn''t'' is used with uncountable nouns. ''Water'' is uncountable. ''There aren''t'' is for plural nouns. ''There wasn''t'' is past tense. ''There isn''t'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ သုံးပါ။","points":1},{"id":1716,"question":"There ________ one table in the classroom.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with singular nouns. ''One table'' is singular. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ သုံးပါ။","points":1},{"id":1717,"question":"There ________ a spider in the bath.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with singular nouns. ''A spider'' is singular. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ သုံးပါ။","points":1},{"id":1718,"question":"There ________ some sugar on the table.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with uncountable nouns. ''Some sugar'' is uncountable. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ သုံးပါ။","points":1},{"id":1719,"question":"There ________ only five weeks until my birthday.","options":["are","is","were"],"answer":"are","explanation":"''There are'' is used with plural nouns. ''Five weeks'' is plural. ''There is'' is for singular nouns. ''There were'' is past tense. ''There are'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1720,"question":"There ________ eight children in the school.","options":["aren''t","isn''t","weren''t"],"answer":"aren''t","explanation":"''There aren''t'' is used with plural nouns. ''Eight children'' is plural. ''There isn''t'' is for singular/uncountable nouns. ''There weren''t'' is past tense. ''There aren''t'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1721,"question":"How many countries ________ there in South America?","options":["are","is","was"],"answer":"are","explanation":"''How many'' is followed by a plural noun and ''are there''. ''Countries'' is plural. ''Is'' is for singular nouns. ''Was'' is past tense. ''How many'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1},{"id":1722,"question":"There ________ any sugar in my coffee.","options":["isn''t","aren''t","wasn''t"],"answer":"isn''t","explanation":"''There isn''t'' is used with uncountable nouns. ''Sugar'' is uncountable. ''There aren''t'' is for plural nouns. ''There wasn''t'' is past tense. ''There isn''t'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ သုံးပါ။","points":1},{"id":1723,"question":"There ________ still a problem.","options":["is","are","were"],"answer":"is","explanation":"''There is'' is used with singular nouns. ''A problem'' is singular. ''There are'' is for plural nouns. ''There were'' is past tense. ''There is'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ သုံးပါ။","points":1},{"id":1724,"question":"________ there any taxis waiting?","options":["Are","Is","Were"],"answer":"Are","explanation":"''Are there'' is used with plural nouns. ''Taxis'' is plural. ''Is there'' is for singular nouns. ''Were there'' is past tense. ''Are there'' ကို အရာဝတ္ထု အများကြီးနဲ့ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1725,"question":"There ________ any trees in my street.","options":["aren''t","isn''t","weren''t"],"answer":"aren''t","explanation":"''There aren''t'' is used with plural nouns. ''Trees'' is plural. ''There isn''t'' is for singular/uncountable nouns. ''There weren''t'' is past tense. ''There aren''t'' ကို အရာဝတ္ထု အများကြီးနဲ့ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

