INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00018000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 18), 'unit18-lesson1', 'There was / There were (Past)', '''There was'' and ''there were'' are used to talk about things that existed in the past. Use ''there was'' with singular nouns and uncountable nouns. Use ''there were'' with plural nouns.', '{"details":[{"concept":"There was + singular noun","explanation":"Use ''there was'' to talk about one thing in the past.","example":"There was a cinema.","burmese":"ရုပ်ရှင်ရုံတစ်ခု ရှိခဲ့တယ်။"},{"concept":"There was + uncountable noun","explanation":"Use ''there was'' with uncountable nouns in the past.","example":"There was some milk.","burmese":"နွားနို့ အနည်းငယ် ရှိခဲ့တယ်။"},{"concept":"There were + plural noun","explanation":"Use ''there were'' to talk about more than one thing in the past.","example":"There were some books.","burmese":"စာအုပ်အချို့ ရှိခဲ့တယ်။"},{"concept":"Negative forms","explanation":"Use ''there wasn''t'' with singular/uncountable nouns and ''there weren''t'' with plural nouns in the past.","example":"There wasn''t a cinema. / There weren''t any books.","burmese":"ရုပ်ရှင်ရုံတစ်ခု မရှိခဲ့ဘူး။ / စာအုပ်တွေ မရှိခဲ့ဘူး။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00018001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 18), 'unit18-lesson2', 'Questions with There was / There were', 'To form past tense questions, put ''was'' or ''were'' before ''there''. Use ''Was there'' with singular nouns and ''Were there'' with plural nouns. To ask about quantities in the past, use ''How many + plural noun + were there?'' and ''How much + uncountable noun + was there?''', '{"details":[{"concept":"Was there + singular noun?","explanation":"Ask about one thing in the past with ''Was there''.","example":"Was there a book on the desk?","burmese":"စာပွင့်ပေါ်မှာ စာအုပ်တစ်အုပ် ရှိခဲ့တာလား။"},{"concept":"Were there + plural noun?","explanation":"Ask about many things in the past with ''Were there''.","example":"Were there any biscuits in the tin?","burmese":"ဘူးထဲမှာ ဘီစကစ် မရှိခဲ့ဘူးလား။"},{"concept":"How many + plural + were there?","explanation":"Ask about quantity in the past with ''How many''.","example":"How many dogs were there in the park?","burmese":"ပန်းခြံထဲမှာ ခွေး ဘယ်နှစ်ကောင် ရှိခဲ့လဲ။"},{"concept":"How much + uncountable + was there?","explanation":"Ask about uncountable quantities in the past with ''How much''.","example":"How much money was there in your bank account?","burmese":"မင်းဘဏ်အကောင့်ထဲမှာ ငွေ ဘယ်လောက် ရှိခဲ့လဲ။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00018000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 18), 'unit18-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1801,"question":"There ________ three strangers outside the office.","options":["was","were","is"],"answer":"were","explanation":"''Were'' is used with plural nouns. ''Three strangers'' is plural. ''There was'' is for singular nouns. ''There is'' is present tense. ''There were'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1802,"question":"________ there a stranger outside the house?","options":["Was","Were","Is"],"answer":"Was","explanation":"''Was there'' is used with singular nouns. ''A stranger'' is singular. ''Were there'' is for plural nouns. ''Is there'' is present tense. ''Was there'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ အတိတ်ကာလ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1803,"question":"There ________ money in the safe.","options":["was","were","has"],"answer":"was","explanation":"''There was'' is used with uncountable nouns. ''Money'' is uncountable. ''There were'' is for plural nouns. ''There has'' is grammatically incorrect here. ''There was'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1804,"question":"There ________ any information in the file.","options":["wasn''t","weren''t","isn''t"],"answer":"wasn''t","explanation":"''There wasn''t'' is used with uncountable nouns. ''Information'' is uncountable. ''There weren''t'' is for plural nouns. ''There isn''t'' is present tense. ''There wasn''t'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1805,"question":"There ________ a Christmas tree in the living room.","options":["wasn''t","weren''t","isn''t"],"answer":"wasn''t","explanation":"''There wasn''t'' is used with singular nouns. ''A Christmas tree'' is singular. ''There weren''t'' is for plural nouns. ''There isn''t'' is present tense. ''There wasn''t'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1806,"question":"There ________ two police officers waiting for you outside.","options":["was","were","is"],"answer":"were","explanation":"''There were'' is used with plural nouns. ''Two police officers'' is plural. ''There was'' is for singular nouns. ''There is'' is present tense. ''There were'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1807,"question":"________ there other factory workers in the construction site?","options":["Was","Were","Are"],"answer":"Were","explanation":"''Were there'' is used with plural nouns. ''Other factory workers'' is plural. ''Was there'' is for singular nouns. ''Are there'' is present tense. ''Were there'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1808,"question":"________ there any water left?","options":["Was","Were","Is"],"answer":"Was","explanation":"''Was there'' is used with uncountable nouns. ''Water'' is uncountable. ''Were there'' is for plural nouns. ''Is there'' is present tense. ''Was there'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ အတိတ်ကာလ မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":1809,"question":"How many drinks ________ there in the restaurant?","options":["were","was","are"],"answer":"were","explanation":"''How many'' is followed by a plural noun and ''were there''. ''Drinks'' is plural. ''Was'' is for singular nouns. ''Are'' is present tense. ''How many'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1810,"question":"How much pollution ________ there in China?","options":["was","were","is"],"answer":"was","explanation":"''How much'' is followed by an uncountable noun and ''was there''. ''Pollution'' is uncountable. ''Were'' is for plural nouns. ''Is'' is present tense. ''How much'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1811,"question":"There ________ any fans in the store.","options":["weren''t","wasn''t","isn''t"],"answer":"weren''t","explanation":"''There weren''t'' is used with plural nouns. ''Fans'' is plural. ''There wasn''t'' is for singular/uncountable nouns. ''There isn''t'' is present tense. ''There weren''t'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1812,"question":"There ________ a black chair in the store.","options":["wasn''t","weren''t","isn''t"],"answer":"wasn''t","explanation":"''There wasn''t'' is used with singular nouns. ''A black chair'' is singular. ''There weren''t'' is for plural nouns. ''There isn''t'' is present tense. ''There wasn''t'' ကို အရာဝတ္ထုတစ်ခုတည်းနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1813,"question":"There ________ many options available to us.","options":["weren''t","wasn''t","isn''t"],"answer":"weren''t","explanation":"''There weren''t'' is used with plural nouns. ''Many options'' is plural. ''There wasn''t'' is for singular/uncountable nouns. ''There isn''t'' is present tense. ''There weren''t'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1814,"question":"How many patients ________ there in the Emergency room?","options":["were","was","are"],"answer":"were","explanation":"''How many'' is followed by a plural noun and ''were there''. ''Patients'' is plural. ''Was'' is for singular nouns. ''Are'' is present tense. ''How many'' ကို အရာဝတ္ထု အများကြီးနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1},{"id":1815,"question":"How much traffic ________ there on the way to work?","options":["was","were","is"],"answer":"was","explanation":"''How much'' is followed by an uncountable noun and ''was there''. ''Traffic'' is uncountable. ''Were'' is for plural nouns. ''Is'' is present tense. ''How much'' ကို တစ်ခါသုံး ဝေါဟာရတွေနဲ့ အတိတ်ကာလမှာ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 19: Although / In spite of
-- --------------------------------------------------------------------------

INSERT INTO units (id, unit_number, title, lesson_count, exercise_count, question_count)
VALUES ('00000019-0000-4000-8000-000000000001', 19, 'Although / In spite of', 2, 1, 15)
ON CONFLICT (unit_number) DO UPDATE SET
  id = EXCLUDED.id,
  title = EXCLUDED.title,
  lesson_count = EXCLUDED.lesson_count,
  exercise_count = EXCLUDED.exercise_count,
  question_count = EXCLUDED.question_count;

INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00019000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 19), 'unit19-lesson1', 'Although + subject + verb', '''Although'' is used to show contrast between two clauses. It is followed by a subject and verb. ''Although'' can come at the beginning or middle of a sentence.', '{"details":[{"concept":"Although + clause (beginning)","explanation":"''Although'' at the start of a sentence connects two contrasting ideas.","example":"Although she ran very fast, she lost the race.","burmese":"သူမ အမြန်ပြေးပေမယ့် ပြိုင်ပွဲမှာ ရှုံးသွားတယ်။"},{"concept":"Although + clause","explanation":"''Although'' connects contrasting clauses even when both are complete sentences.","example":"Although it rained all day, we enjoyed the party very much.","burmese":"မိုးတစ်နေ့လုံး ရွာခဲ့ပေမယ့် ငါတို့ ပါတီကို ပျော်ရွှင်စွာ ဖြတ်သန်းခဲ့တယ်။"},{"concept":"Although + clause (end)","explanation":"''Although'' can also appear at the end of a sentence.","example":"They are generous although they are poor.","burmese":"သူတို့ ဆင်းရဲပေမယ့် ပေးကမ်းစွန့်ကြဲတတ်ကြတယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00019001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 19), 'unit19-lesson2', 'In spite of + noun / Ving', '''In spite of'' is used to show contrast and is followed by a noun or a gerund (Ving). It has the same meaning as ''although'' but requires a different structure.', '{"details":[{"concept":"In spite of + noun","explanation":"''In spite of'' is followed by a noun phrase to show contrast.","example":"In spite of their quarrel, they remain the best of friends.","burmese":"ရန်ဖြစ်ထားပေမယ့်ပဲ အကောင်းဆုံး သငယ်ချင်းဖြစ်နေကြတန်ပါ။"},{"concept":"In spite of + noun","explanation":"''In spite of'' can show contrast with a simple noun.","example":"We went out in spite of the rain.","burmese":"မိုးရွာပေမယ့်ပဲ ငါတို့ အပြင်ထွက်ခဲ့တယ်။"},{"concept":"In spite of + Ving","explanation":"''In spite of'' is followed by a gerund (-ing form) when the contrast involves an action.","example":"In spite of completing his master''s degree, he could not find a quality job.","burmese":"မောစတာဘွဲ့ရပေမယ့်ပဲ သူ အလုပ်ကောင်းကောင်း မရခဲ့ဘူး။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00019000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 19), 'unit19-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":1901,"question":"________ she is beautiful, everybody hates her.","options":["Although","In spite of","Because"],"answer":"Although","explanation":"''Although'' is followed by a clause with subject + verb. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning to cause. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1902,"question":"The children slept deeply ________ the noise.","options":["in spite of","although","because of"],"answer":"in spite of","explanation":"''In spite of'' is followed by a noun. ''The noise'' is a noun. ''Although'' needs subject + verb. ''Because of'' changes the meaning. ''In spite of'' ကို noun ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1903,"question":"________ earning a low salary, Sara helped her parents.","options":["In spite of","Although","Because"],"answer":"In spite of","explanation":"''In spite of'' is followed by Ving (gerund). ''Earning'' is a gerund. ''Although'' needs subject + verb. ''Because'' changes the meaning. ''In spite of'' ကို Ving ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1904,"question":"Jane rarely sees Alan ________ they are neighbors.","options":["although","in spite of","because"],"answer":"although","explanation":"''Although'' is followed by a clause with subject + verb. ''They are neighbors'' is a clause. ''In spite of'' needs a noun or Ving. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1905,"question":"Kate did not do well in the exam ________ working very hard.","options":["in spite of","although","because of"],"answer":"in spite of","explanation":"''In spite of'' is followed by Ving. ''Working'' is a gerund. ''Although'' needs subject + verb. ''Because of'' changes the meaning. ''In spite of'' ကို Ving ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1906,"question":"________ I was very hungry, I couldn''t eat.","options":["Although","In spite of","Because"],"answer":"Although","explanation":"''Although'' is followed by a clause with subject + verb. ''I was very hungry'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1907,"question":"________ the difficulty, they managed to solve the maths problem.","options":["In spite of","Although","Because of"],"answer":"In spite of","explanation":"''In spite of'' is followed by a noun. ''The difficulty'' is a noun. ''Although'' needs subject + verb. ''Because of'' changes the meaning. ''In spite of'' ကို noun ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1908,"question":"Liz never talked to him ________ she loved him.","options":["although","in spite of","because"],"answer":"although","explanation":"''Although'' is followed by a clause with subject + verb. ''She loved him'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1909,"question":"________ it was cold, Marie didn''t put on her coat.","options":["Although","In spite of","Because"],"answer":"Although","explanation":"''Although'' is followed by a clause with subject + verb. ''It was cold'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1910,"question":"Clare did the work ________ being ill.","options":["in spite of","although","because of"],"answer":"in spite of","explanation":"''In spite of'' is followed by Ving. ''Being'' is a gerund. ''Although'' needs subject + verb. ''Because of'' changes the meaning. ''In spite of'' ကို Ving ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1911,"question":"________ the weather was bad, we had a good time.","options":["Although","In spite of","Because"],"answer":"Although","explanation":"''Although'' is followed by a clause with subject + verb. ''The weather was bad'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1912,"question":"________ we had planned everything carefully, a lot of things went wrong.","options":["Although","In spite of","Because"],"answer":"Although","explanation":"''Although'' is followed by a clause with subject + verb. ''We had planned everything carefully'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1913,"question":"I went to work the next day ________ I was still feeling ill.","options":["although","in spite of","because"],"answer":"although","explanation":"''Although'' is followed by a clause with subject + verb. ''I was still feeling ill'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1914,"question":"She accepted the job ________ the low salary.","options":["in spite of","although","because of"],"answer":"in spite of","explanation":"''In spite of'' is followed by a noun. ''The low salary'' is a noun. ''Although'' needs subject + verb. ''Because of'' changes the meaning. ''In spite of'' ကို noun ရဲ့ ရှေ့မှာ သုံးပါ။","points":1},{"id":1915,"question":"I managed to sleep ________ the hotel was noisy.","options":["although","in spite of","because"],"answer":"although","explanation":"''Although'' is followed by a clause with subject + verb. ''The hotel was noisy'' is a clause. ''In spite of'' needs a noun or Ving. ''Because'' changes the meaning. ''Although'' ကို clause ရဲ့ ရှေ့မှာ သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

